CREATE TABLE IF NOT EXISTS workforce_job_requisitions(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,title TEXT NOT NULL,department TEXT NOT NULL,description TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'DRAFT',approval_status TEXT NOT NULL DEFAULT 'PENDING',created_by TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS workforce_onboarding_cases(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,employee_email TEXT NOT NULL,role_code TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'PREPARING',profile_photo_object_key TEXT,consent_recorded_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS workforce_access_locker(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,employee_email TEXT NOT NULL,resource_type TEXT NOT NULL,resource_name TEXT NOT NULL,access_level TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'PLANNED',external_reference TEXT,issued_at TEXT,revoked_at TEXT,UNIQUE(organization_id,property_id,employee_email,resource_type,resource_name));
CREATE TABLE IF NOT EXISTS workforce_property_custody(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,employee_email TEXT NOT NULL,asset_type TEXT NOT NULL,asset_identifier TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'ASSIGNED',issued_at TEXT NOT NULL,returned_at TEXT,condition_note TEXT);
CREATE TABLE IF NOT EXISTS workforce_separation_cases(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,employee_email TEXT NOT NULL,effective_at TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'PREPARED',access_revocation_status TEXT NOT NULL DEFAULT 'PENDING',property_return_status TEXT NOT NULL DEFAULT 'PENDING',approved_by TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_workforce_onboarding_scope ON workforce_onboarding_cases(organization_id,property_id,status);
CREATE INDEX IF NOT EXISTS idx_workforce_separation_scope ON workforce_separation_cases(organization_id,property_id,status);
